#include "renderer/MaterialBinding.hpp"
#include <glm/gtc/type_ptr.hpp>
namespace scene_editor {void MaterialBinding::bind(const Material& m,const ShaderProgram& s){glUniform3fv(s.uniform("baseColor"),1,glm::value_ptr(m.color));glUniform3fv(s.uniform("ambientColor"),1,glm::value_ptr(m.ambient));glUniform3fv(s.uniform("diffuseColor"),1,glm::value_ptr(m.diffuse));glUniform3fv(s.uniform("specularColor"),1,glm::value_ptr(m.specular));glUniform3fv(s.uniform("emissionColor"),1,glm::value_ptr(m.emission));glUniform1f(s.uniform("emissionStrength"),m.emissionStrength);glUniform1f(s.uniform("shininess"),m.shininess);bool present=false;if(!m.texturePath.empty()){auto& texture=textures_[m.texturePath];if(!texture){auto candidate=std::make_unique<Texture>();if(candidate->load(m.texturePath))texture=std::move(candidate);}if(texture&&texture->id){glActiveTexture(GL_TEXTURE0);glBindTexture(GL_TEXTURE_2D,texture->id);present=true;}}glUniform1i(s.uniform("hasTexture"),present?1:0);glUniform1i(s.uniform("diffuseTexture"),0);}}
